import{z as n,x as E,o as i,c as p,q as A,j as l,D as r,d as t,s as o,S as I,b as e}from"./chunks/framework.C8m1ZpeB.js";const u=JSON.parse('{"title":"I²C / SPI / UART","description":"","frontmatter":{"title":"I²C / SPI / UART","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/i2c-spi-uart.md","filePath":"cs/i2c-spi-uart.md","lastUpdated":1791063341000}'),C={name:"cs/i2c-spi-uart.md"};function S(d,a,P,B,c,D){const s=E("Mermaid");return i(),p("div",null,[a[2]||(a[2]=A('<h1 id="i2c-spi-uart" tabindex="-1">I²C / SPI / UART <a class="header-anchor" href="#i2c-spi-uart" aria-label="Permalink to &quot;I²C / SPI / UART&quot;">​</a></h1><div class="epigraph"><p>片上与板级低速外设用两根线（I²C）、选通时钟（SPI）或异步起止位（UART）：没有 TLP，没有 FTL，只有移位寄存器与时序。</p><footer>—— 据 NXP, I²C-bus Specification；Motorola/Freescale SPI 实践；Harris and Harris, Digital Design and Computer Architecture 整理</footer></div><p><a href="/cs/usb-protocol">上一课</a>是主机树与 DMA 环。SoC 上大量传感器、电源管理芯片、启动 ROM 旁的小闪存并不走 USB。缺口是 <strong>I²C、SPI、UART</strong> 这组位移总线，接回 <a href="/cs/verilog-basics">Verilog</a> 能写的状态机，并对照 PCIe 的重。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>UART：双方独立时钟，起止位框字节，波特率约定。I²C：SCL/SDA 开漏、地址+ACK、多主仲裁。SPI：SCLK+MOSI+MISO+CS，全双工移位，模式 0–3 定义边沿。缺口不是 USB 描述符，而是这些协议如何被 MMIO 寄存器（或 bit-bang GPIO）驱动，以及为何启动早期用 UART 打日志、用 SPI 读 BIOS 闪存。</p><p><span class="marginnote">「开漏」翻译成大白话：引脚只会「拉到地」，不会主动推高电平；想输出 1 就松手，靠上拉电阻把线慢慢拽回高。多个设备同时拉低不会打架（线与），但翻转慢——这是 I²C 只有几百 kHz 到几 MHz 的根源之一。</span></p><p>速度：通常 Mb/s 级，不是 PCIe GB/s。DMA 可选（UART FIFO、SPI 块），不是必须。</p><h3 id="i2c-不是「慢-pcie」" tabindex="-1">I²C 不是「慢 PCIe」 <a class="header-anchor" href="#i2c-不是「慢-pcie」" aria-label="Permalink to &quot;I²C 不是「慢 PCIe」&quot;">​</a></h3><p>无配置空间 BAR 树，无事务层重传（I²C 只有 ACK/NACK）。把 PMIC 当 PCIe 端点枚举会失败。SPI 闪存的命令字节（读 JEDEC ID、页写）是另一套，与 NAND ONFI 不同。</p><p><span class="marginnote">NXP I²C 规范；SPI 是事实标准。Harris 有 UART/SPI 实验。EIA-232 是 UART 的电气历史。本课钉数字时序，不画 RS-232 电平转换器。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>驱动：写波特率除数、填 FIFO、轮询或中断（可接 <a href="/cs/plic-irq">PLIC</a>/GIC，通常不是 MSI-X）。I²C 状态机：start、地址、数据、stop；时钟拉伸。SPI：拉低 CS，移 N 拍。与 <a href="/cs/async-fifo-cdc">CDC</a>：外设时钟域与 CPU 不同时用 FIFO。复位后引脚复用要先配。</p><p><span class="marginnote">数字实例：115200 波特即每秒约 115200 位，一个 10 位帧（1 起始 + 8 数据 + 1 停止）约 87 微秒，每秒最多约 1.1 万字节；SPI 常跑几十 MHz，快三个数量级。这就是「日志走 UART、镜像走 SPI」的速度理由。</span></p>',13)),(i(),l(I,null,{default:r(()=>[o(s,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20UART%5B%22%E5%BC%82%E6%AD%A5%E8%B5%B7%E6%AD%A2%22%5D%20--%3E%20MMIO%5B%22%E6%8E%A7%E5%88%B6%E5%99%A8%E5%AF%84%E5%AD%98%E5%99%A8%22%5D%0A%20%20I2C%5B%22%E5%BC%80%E6%BC%8F%E5%9C%B0%E5%9D%80%E5%8C%85%22%5D%20--%3E%20MMIO%0A%20%20SPI%5B%22%E9%80%89%E9%80%9A%E7%A7%BB%E4%BD%8D%22%5D%20--%3E%20MMIO%0A%20%20MMIO%20--%3E%20LATER%5B%22%E5%90%8E%E8%AF%BE%EF%BC%9A%E6%98%BE%E7%A4%BA%E6%98%AF%E9%AB%98%E5%B8%A6%E5%AE%BD%E5%B8%A7%E7%BC%93%E5%86%B2%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[t(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("p",null,"固件用 SPI 读引导镜像，下一课帧缓冲则常走内存+扫描 DMA。",-1)),a[4]||(a[4]=e("h2",{id:"机制",tabindex:"-1"},[t("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=e("p",null,"BIOS/UEFI 课会在 SPI 闪存里取代码，用 UART 报错，用 I²C 读 SPD（DIMM 信息）——把低速总线接到启动。本课先交协议。HDL 实现这些控制器是状态机作业，综合进 ASIC/FPGA。",-1)),a[6]||(a[6]=e("p",null,[e("span",{class:"marginnote"},"「时钟拉伸」可以类比：从机一时答不上来，就按住老师的粉笔（把 SCL 拉低），主机只能等。SPI 没有这种机制，主机照吹时钟、从机跟不上就出错，只能按最慢设备预设频率。这也是 I²C 能「快慢混挂」、SPI 讲究门当户对的原因之一。")],-1)),(i(),l(I,null,{default:r(()=>[o(s,{id:"mermaid-50",class:"mermaid",graph:"flowchart%20LR%0A%20%20S%5B%22START%22%5D%20--%3E%20A%5B%22%E5%9C%B0%E5%9D%80%20%2B%20%E8%AF%BB%2F%E5%86%99%E4%BD%8D%22%5D%0A%20%20A%20--%3E%20AK%5B%22%E4%BB%8E%E6%9C%BA%20ACK%22%5D%0A%20%20AK%20--%3E%20D0%5B%22%E6%95%B0%E6%8D%AE%E5%AD%97%E8%8A%82%22%5D%0A%20%20D0%20--%3E%20AK2%5B%22ACK%20%E6%88%96%20NACK%22%5D%0A%20%20AK2%20--%3E%20SP%5B%22STOP%22%5D%0A"})]),fallback:r(()=>[...a[1]||(a[1]=[t(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=A('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写 CAN/LIN 汽车总线全书，不把 I3C 当 I²C 的必替换。不讨论电磁兼容认证。不进入传感器融合算法。</p><p>后课默认：板级低速器用 UART/I²C/SPI；高速块与 GPU 走 PCIe/内存。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>UART 异步、I²C 寻址开漏、SPI 选通全双工。</li><li>MMIO 状态机即可，DMA 可选。</li><li>启动路径常依赖 SPI 闪存与 UART。</li><li>出处：NXP I²C Spec；SPI 实践；Harris and Harris。</li></ul>',5))])}const h=n(C,[["render",S]]);export{u as __pageData,h as default};
